fn rotate(a: Vec<i32>, offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }

    let k = offset % n;
    if k == 0 {
        return a;
    }

    let mut b = Vec::with_capacity(n);
    // b[i] = a[(i + k) % n]
    for i in 0..n {
        let src = i + k;
        let idx = if src >= n { src - n } else { src };
        b.push(a[idx]);
    }
    b
}